__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"legalFr",{enumerable:!0,get:function(){return t}});var s=r(d[0]);const n=`${s.OPERATOR.name} (num\xe9ro d\u2019entreprise ${s.OPERATOR.enterprise}, TVA ${s.OPERATOR.vat}), ${s.OPERATOR.address}`,t={updated:"En vigueur depuis le 21 octobre 2026",nav:{mentions:"Mentions l\xe9gales",conditions:"Conditions g\xe9n\xe9rales",confidentialite:"Confidentialit\xe9",cookies:"Cookies",suppression:"Supprimer mon compte"},docs:{mentions:{title:"Mentions l\xe9gales",sections:[{title:"\xc9diteur",body:[`BatiNode (${s.OPERATOR.site}) est \xe9dit\xe9 et exploit\xe9 par ${n}.`,`Contact : ${s.OPERATOR.email}.`]},{title:"H\xe9bergement",body:["L\u2019application web est servie par GitHub Pages (GitHub, Inc., 88 Colin P. Kelly Jr. Street, San Francisco, CA 94107, \xc9tats-Unis).","Les donn\xe9es des comptes, les demandes, les offres et les fichiers sont h\xe9berg\xe9s par Supabase, Inc. dans un centre de donn\xe9es situ\xe9 \xe0 Francfort (Allemagne, Union europ\xe9enne)."]},{title:"Propri\xe9t\xe9 intellectuelle",body:[`La marque BatiNode, le logo, Nodi, les textes, les illustrations et le code de l\u2019application appartiennent \xe0 ${s.OPERATOR.name}. Toute reproduction sans autorisation \xe9crite est interdite.`,"Les noms, logos et contenus des entreprises inscrites restent la propri\xe9t\xe9 de ces entreprises."]},{title:"Signaler un contenu",body:[`Pour signaler un contenu illicite ou une erreur, \xe9crivez \xe0 ${s.OPERATOR.email}. Nous r\xe9pondons dans les meilleurs d\xe9lais.`]}]},conditions:{title:"Conditions g\xe9n\xe9rales d\u2019utilisation et de vente",sections:[{title:"1. Objet",body:[`Les pr\xe9sentes conditions r\xe9gissent l\u2019utilisation de BatiNode, plateforme exploit\xe9e par ${n}, et les abonnements qui y sont vendus.`,"En cr\xe9ant un compte, en r\xe9pondant \xe0 une demande de prix ou en utilisant l\u2019application, vous acceptez ces conditions au nom de l\u2019entreprise que vous repr\xe9sentez."]},{title:"2. Une plateforme r\xe9serv\xe9e aux professionnels",body:["BatiNode s\u2019adresse uniquement aux entreprises : entrepreneurs du b\xe2timent, fournisseurs de mat\xe9riaux et architectes. Chaque entreprise doit disposer d\u2019un num\xe9ro d\u2019entreprise belge actif.","Nous v\xe9rifions le num\xe9ro de TVA (VIES) et l\u2019inscription \xe0 la Banque-Carrefour des Entreprises, \xe0 l\u2019inscription puis r\xe9guli\xe8rement. Un compte dont l\u2019entreprise n\u2019est pas active ou dont les informations sont inexactes peut \xeatre suspendu.","Vous \xeates responsable des informations que vous donnez, de la confidentialit\xe9 de votre mot de passe et de ce qui est fait avec votre compte. Signalez-nous sans attendre tout usage non autoris\xe9."]},{title:"3. Les services",body:["BatiNode permet notamment : d\u2019envoyer des demandes de prix \xe0 des fournisseurs et de comparer leurs offres, d\u2019\xe9mettre des bons de commande, d\u2019\xe9changer avec d\u2019autres entreprises dans le R\xe9seau d\u2019entrepreneurs (sous-traitance et partenariats), de g\xe9rer des fichiers, et d\u2019\xeatre aid\xe9 par Nodi, l\u2019assistant de BatiNode.","Les fonctions disponibles d\xe9pendent de l\u2019abonnement choisi, comme indiqu\xe9 sur la page Abonnement de l\u2019application."]},{title:"4. Le r\xf4le de BatiNode",body:["BatiNode met en relation des entreprises. Nous ne sommes pas partie aux contrats conclus entre elles : la vente de mat\xe9riaux est conclue directement entre l\u2019entrepreneur et le fournisseur, aux conditions de leur offre et de leur bon de commande.","Nous ne garantissons ni les prix, ni la qualit\xe9, ni les d\xe9lais, ni la solvabilit\xe9 des utilisateurs. La v\xe9rification des entreprises r\xe9duit les risques mais ne les supprime pas.","Lorsqu\u2019aucun fournisseur n\u2019est choisi par l\u2019entrepreneur, BatiNode s\xe9lectionne des fournisseurs de la r\xe9gion selon leur activit\xe9 et leur proximit\xe9, sans contrepartie de leur part."]},{title:"5. Abonnements des entrepreneurs",body:["Un nouvel entrepreneur peut essayer gratuitement l\u2019abonnement Premium pendant 7 jours, sans carte de paiement. \xc0 la fin de l\u2019essai, l\u2019acc\xe8s aux fonctions payantes s\u2019arr\xeate jusqu\u2019au choix d\u2019un abonnement.","Prix de lancement hors TVA : Starter 69,99 \u20ac par mois ou 699,90 \u20ac par an ; Premium 129,99 \u20ac par mois ou 1 299,90 \u20ac par an. La TVA belge s\u2019ajoute au prix.","Garantie fondateur : une entreprise qui s\u2019abonne pendant la phase de lancement, c\u2019est-\xe0-dire parmi les 50 premi\xe8res entreprises \xe0 payer un abonnement et au plus tard le 31 mars 2027 (heure belge), re\xe7oit un num\xe9ro de fondateur et garde son prix de lancement \xe0 vie, tant que son abonnement reste actif sans interruption et sur le m\xeame plan. Le fondateur peut passer une seule fois de Starter \xe0 Premium en gardant cette garantie, au prix de lancement de Premium. Elle prend fin si l\u2019abonnement est r\xe9sili\xe9, s\u2019il passe \xe0 une formule inf\xe9rieure ou s\u2019il change de formule une seconde fois.","Le paiement est trait\xe9 par Stripe. L\u2019abonnement est payable d\u2019avance et se renouvelle automatiquement \xe0 la fin de chaque p\xe9riode, au prix en vigueur.","Satisfait ou rembours\xe9 : votre premier paiement d\u2019abonnement vous est rembours\xe9 int\xe9gralement si vous le demandez \xe0 support@batinode.be dans les 30 jours qui le suivent, sans justification. L\u2019abonnement est alors r\xe9sili\xe9 et la place de fondateur \xe9ventuelle n\u2019est pas r\xe9attribu\xe9e. Cette garantie ne vaut qu\u2019une fois par entreprise.","Vous pouvez r\xe9silier \xe0 tout moment depuis l\u2019application : la r\xe9siliation prend effet \xe0 la fin de la p\xe9riode pay\xe9e, sans remboursement de la p\xe9riode en cours.","Sous r\xe9serve de la garantie fondateur, nous annon\xe7ons toute hausse de prix au moins 30 jours \xe0 l\u2019avance ; elle s\u2019applique \xe0 partir de la p\xe9riode suivante et vous pouvez r\xe9silier avant.","Les abonnements \xe9tant vendus \xe0 des entreprises, le droit de r\xe9tractation pr\xe9vu pour les consommateurs ne s\u2019applique pas."]},{title:"6. Fournisseurs",body:["Un fournisseur peut r\xe9pondre \xe0 une demande de prix depuis le lien re\xe7u par e-mail, sans compte. R\xe9pondre est gratuit.","Une offre remise engage le fournisseur aux prix et conditions indiqu\xe9s, jusqu\u2019\xe0 sa date de validit\xe9. Le fournisseur reste responsable de son offre, y compris lorsqu\u2019il a joint un PDF et que Nodi en a repris les prix : il v\xe9rifie le formulaire avant de l\u2019envoyer.","Si une commission sur les commandes devait \xeatre introduite, son taux serait affich\xe9 et accept\xe9 express\xe9ment avant toute offre concern\xe9e. Elle ne s\u2019appliquerait jamais aux offres d\xe9j\xe0 remises.","Un fournisseur peut cesser de recevoir les demandes \xe0 tout moment, en un clic depuis l\u2019e-mail ou la page de l\u2019offre."]},{title:"7. Nodi et l\u2019intelligence artificielle",body:["Nodi utilise un mod\xe8le d\u2019intelligence artificielle pour r\xe9pondre aux questions, lire les offres jointes en PDF, r\xe9diger les actualit\xe9s et reformuler ou traduire les messages entre entrepreneurs et fournisseurs. Les coordonn\xe9es sont retir\xe9es des messages relay\xe9s.","Les r\xe9ponses de Nodi peuvent contenir des erreurs. Elles ne remplacent pas un conseil professionnel (technique, juridique ou fiscal). V\xe9rifiez toujours les montants et les informations importantes.","Les actualit\xe9s publi\xe9es par Nodi r\xe9sument des articles de sources externes, dont le lien est indiqu\xe9. Ces sources restent responsables de leur contenu."]},{title:"8. Usages interdits",body:["Il est interdit notamment : de publier un contenu illicite, trompeur, injurieux ou portant atteinte aux droits d\u2019autrui ; d\u2019envoyer des messages publicitaires non sollicit\xe9s ; d\u2019extraire en masse les donn\xe9es de la plateforme ; de tenter d\u2019acc\xe9der aux comptes ou donn\xe9es d\u2019autrui ; de perturber le fonctionnement du service ; de cr\xe9er un compte pour une entreprise que vous ne repr\xe9sentez pas."]},{title:"9. Vos contenus",body:["Vous restez propri\xe9taire des contenus que vous d\xe9posez (demandes, offres, fichiers, messages, logo). Vous nous accordez le droit de les h\xe9berger, de les afficher aux destinataires choisis et de les traiter dans la seule mesure n\xe9cessaire au fonctionnement du service."]},{title:"10. Disponibilit\xe9 et responsabilit\xe9",body:["Nous faisons le n\xe9cessaire pour que BatiNode soit disponible et s\xfbr, sans pouvoir garantir un service sans interruption ni erreur. Des maintenances peuvent avoir lieu.",`Sauf faute intentionnelle ou faute grave, la responsabilit\xe9 de ${s.OPERATOR.name} est limit\xe9e aux dommages directs et plafonn\xe9e aux montants pay\xe9s par votre entreprise \xe0 BatiNode pendant les 12 mois pr\xe9c\xe9dant le fait dommageable. Nous ne r\xe9pondons pas des dommages indirects, tels que perte de chiffre d\u2019affaires, de client\xe8le ou de donn\xe9es.`]},{title:"11. Suspension et fin",body:["Vous pouvez arr\xeater d\u2019utiliser BatiNode et demander la suppression de votre compte \xe0 tout moment.","Nous pouvons suspendre ou fermer un compte qui ne respecte pas ces conditions, apr\xe8s un avertissement sauf urgence (fraude, s\xe9curit\xe9, contenu illicite)."]},{title:"12. Donn\xe9es personnelles",body:["Le traitement des donn\xe9es personnelles est d\xe9crit dans la politique de confidentialit\xe9, qui fait partie des pr\xe9sentes conditions."]},{title:"13. Modification des conditions",body:["Nous pouvons adapter ces conditions. Toute modification importante vous est annonc\xe9e au moins 30 jours avant son entr\xe9e en vigueur, par e-mail ou dans l\u2019application. Si vous refusez la modification, vous pouvez r\xe9silier avant cette date."]},{title:"14. Droit applicable et litiges",body:["Ces conditions sont soumises au droit belge. En cas de d\xe9saccord, \xe9crivez-nous d\u2019abord : nous cherchons une solution amiable.","\xc0 d\xe9faut, les tribunaux de l\u2019arrondissement judiciaire de Bruxelles sont seuls comp\xe9tents."]}]},confidentialite:{title:"Politique de confidentialit\xe9",sections:[{title:"Responsable du traitement",body:[`${n} est responsable du traitement des donn\xe9es personnelles collect\xe9es via BatiNode. Pour toute question ou demande : ${s.OPERATOR.email}.`]},{title:"Donn\xe9es trait\xe9es",body:["Compte : nom, adresse e-mail, t\xe9l\xe9phone, langue et mot de passe (conserv\xe9 uniquement sous forme chiffr\xe9e).","Entreprise : nom, num\xe9ro de TVA, adresse, donn\xe9es publiques de la Banque-Carrefour des Entreprises, logo, m\xe9tiers, zones d\u2019activit\xe9, taille et informations donn\xe9es \xe0 l\u2019inscription.","Activit\xe9 : demandes de prix, offres, bons de commande, documents, fichiers, messages, publications dans le R\xe9seau d\u2019entrepreneurs et questions pos\xe9es \xe0 Nodi.","Paiement : l\u2019abonnement et son \xe9tat. Les donn\xe9es de carte sont trait\xe9es directement par Stripe ; nous n\u2019y avons pas acc\xe8s.","Technique : journaux de connexion et d\u2019erreurs, adresse IP, pour la s\xe9curit\xe9 du service.","Fournisseurs : l\u2019annuaire contient des coordonn\xe9es professionnelles de fournisseurs de mat\xe9riaux (nom de l\u2019entreprise, adresse, e-mail et t\xe9l\xe9phone professionnels, activit\xe9), issues de sources publiques comme leur site internet ou la Banque-Carrefour des Entreprises."]},{title:"Pourquoi et sur quelle base",body:["Fournir le service (compte, demandes, offres, commandes, R\xe9seau d\u2019entrepreneurs, abonnement) : ex\xe9cution du contrat.","Facturation et comptabilit\xe9 : obligation l\xe9gale.","V\xe9rifier les entreprises, pr\xe9venir la fraude, s\xe9curiser la plateforme : int\xe9r\xeat l\xe9gitime \xe0 garder une plateforme fiable.","Transmettre les demandes de prix aux fournisseurs de l\u2019annuaire : int\xe9r\xeat l\xe9gitime des entrepreneurs et des fournisseurs \xe0 se rencontrer entre professionnels. Chaque e-mail permet de s\u2019y opposer en un clic.","Vous informer des \xe9volutions du service : int\xe9r\xeat l\xe9gitime ; vous pouvez vous y opposer \xe0 tout moment."]},{title:"Qui voit vos donn\xe9es",body:["Les fournisseurs \xe0 qui une demande est envoy\xe9e voient le nom, le num\xe9ro de TVA et l\u2019adresse de l\u2019entreprise qui demande, ainsi que le contenu de la demande. L\u2019entrepreneur voit les offres et le nom des fournisseurs. Les coordonn\xe9es personnelles sont retir\xe9es des messages relay\xe9s.","Nos sous-traitants, uniquement pour faire fonctionner BatiNode : Supabase (base de donn\xe9es et fichiers, Francfort, UE), GitHub (h\xe9bergement de l\u2019application web), Brevo (envoi des e-mails, France), Stripe (paiements) et Anthropic (le mod\xe8le d\u2019intelligence artificielle de Nodi). Selon ses conditions commerciales, Anthropic n\u2019utilise pas ces donn\xe9es pour entra\xeener ses mod\xe8les.","Uniquement si vous l\u2019acceptez dans le bandeau cookies de la version web : Meta Platforms Ireland (pixel Meta), pour mesurer nos publicit\xe9s Facebook et Instagram. Il re\xe7oit les pages visit\xe9es et le fait qu\u2019une inscription ou un abonnement a eu lieu, jamais vos coordonn\xe9es, et ne fonctionne jamais sur les liens envoy\xe9s aux fournisseurs.","Certains de ces prestataires peuvent traiter des donn\xe9es hors de l\u2019Union europ\xe9enne, notamment aux \xc9tats-Unis. Ces transferts sont encadr\xe9s par le cadre de protection des donn\xe9es UE\u2013\xc9tats-Unis ou par les clauses contractuelles types de la Commission europ\xe9enne.","Les membres connect\xe9s de BatiNode voient, dans la liste des entrepreneurs inscrits, le nom de votre entreprise, votre commune, vos m\xe9tiers et les badges \xab V\xe9rifi\xe9 BCE \xbb et \xab Fondateur \xbb. Jamais votre e-mail, votre t\xe9l\xe9phone ni votre num\xe9ro de TVA. Vous pouvez quitter cette liste \xe0 tout moment dans R\xe9glages.","Nous ne vendons jamais vos donn\xe9es."]},{title:"Dur\xe9e de conservation",body:["Les donn\xe9es du compte et de l\u2019activit\xe9 sont conserv\xe9es tant que le compte est actif, puis supprim\xe9es ou anonymis\xe9es dans les 30 jours d\u2019une demande de suppression, sauf ce que la loi nous oblige \xe0 garder (factures et pi\xe8ces comptables, pendant la dur\xe9e l\xe9gale).","Les journaux techniques sont conserv\xe9s au plus 12 mois.","Les coordonn\xe9es d\u2019un fournisseur de l\u2019annuaire sont conserv\xe9es jusqu\u2019\xe0 ce qu\u2019il s\u2019y oppose ; nous gardons alors seulement de quoi respecter son refus."]},{title:"Vos droits",body:[`Vous pouvez demander l\u2019acc\xe8s \xe0 vos donn\xe9es, leur rectification, leur effacement, la limitation du traitement, leur portabilit\xe9, et vous opposer au traitement fond\xe9 sur notre int\xe9r\xeat l\xe9gitime. \xc9crivez \xe0 ${s.OPERATOR.email} ; nous r\xe9pondons dans un d\xe9lai d\u2019un mois.`,"Vous pouvez aussi introduire une plainte aupr\xe8s de l\u2019Autorit\xe9 de protection des donn\xe9es, rue de la Presse 35, 1000 Bruxelles (www.autoriteprotectiondonnees.be)."]},{title:"S\xe9curit\xe9",body:["Les \xe9changes sont chiffr\xe9s (HTTPS), les mots de passe sont chiffr\xe9s, chaque entreprise n\u2019acc\xe8de qu\u2019\xe0 ses propres donn\xe9es, les fichiers sont priv\xe9s et ne s\u2019ouvrent que par des liens temporaires, et l\u2019acc\xe8s d\u2019administration est limit\xe9."]}]},cookies:{title:"Cookies et stockage local",sections:[{title:"Ce que nous utilisons",body:["Sur la version web, le pixel Meta (Facebook, Instagram) ne s\u2019active que si vous cliquez sur \xab Accepter \xbb dans le bandeau ; \xab Refuser \xbb est aussi simple. Il sert \xe0 mesurer nos publicit\xe9s : pages vues, inscription, abonnement, sans vos coordonn\xe9es. Il d\xe9pose le cookie \xab _fbp \xbb (jusqu\u2019\xe0 90 jours) et transmet ces informations \xe0 Meta Platforms Ireland, qui peut les relier \xe0 votre compte Facebook ou Instagram. Votre choix est gard\xe9 6 mois ; le lien \xab Choix cookies \xbb en bas des pages publiques permet de le changer. L\u2019application iPhone et Android n\u2019utilise pas ce pixel.","Pour le reste, l\u2019application garde dans votre navigateur ou votre t\xe9l\xe9phone uniquement ce qui est n\xe9cessaire \xe0 son fonctionnement : votre session de connexion, la langue choisie et quelques pr\xe9f\xe9rences d\u2019affichage (par exemple un brouillon de demande en cours). Ces \xe9l\xe9ments sont strictement n\xe9cessaires et ne demandent donc pas de consentement."]},{title:"Paiement",body:["La page de paiement est fournie par Stripe sur son propre site. Stripe y utilise ses cookies, n\xe9cessaires \xe0 la s\xe9curit\xe9 du paiement et \xe0 la pr\xe9vention de la fraude, selon sa propre politique."]},{title:"Les effacer",body:["Vous pouvez effacer ces donn\xe9es \xe0 tout moment en vous d\xe9connectant ou depuis les r\xe9glages de votre navigateur. Vous devrez alors vous reconnecter."]}]},suppression:{title:"Supprimer votre compte BatiNode",sections:[{title:"Depuis l\u2019application",body:["Ouvrez R\xe9glages, puis \xab Supprimer mon compte \xbb, et confirmez. La suppression est imm\xe9diate et d\xe9finitive."]},{title:"Sans l\u2019application",body:[`\xc9crivez \xe0 ${s.OPERATOR.email} depuis l\u2019adresse e-mail de votre compte en demandant la suppression. Nous la faisons dans les 30 jours et vous le confirmons.`]},{title:"Ce qui est supprim\xe9",body:["Votre acc\xe8s et vos donn\xe9es personnelles. Si vous \xeates le dernier utilisateur de votre entreprise : son abonnement est arr\xeat\xe9, ses fichiers, son logo, ses annonces et ses conversations sont effac\xe9s.","Ce qui est conserv\xe9 : les commandes, offres et pi\xe8ces comptables dont vos partenaires ou nous-m\xeames avons besoin pour respecter la loi, pendant la dur\xe9e l\xe9gale, sans vos coordonn\xe9es."]}]}}}},1047,[1048]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEGAL_PAGES",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"OPERATOR",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"LEGAL_UPDATED",{enumerable:!0,get:function(){return o}}),e.isLegalPage=function(t){return n.includes(t??"")};const n=["mentions","conditions","confidentialite","cookies","suppression"],t={name:"Modern X Renov SRL",nameNl:"Modern X Renov BV",enterprise:"1015.519.625",vat:"BE 1015.519.625",address:"Ruisbroeksesteenweg 9, 1600 Sint-Pieters-Leeuw, Belgique",addressNl:"Ruisbroeksesteenweg 9, 1600 Sint-Pieters-Leeuw, Belgi\xeb",email:"support@batinode.be",site:"app.batinode.be"},o="2026-10-20"},1048,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"legalNl",{enumerable:!0,get:function(){return o}});var n=r(d[0]);const t=`${n.OPERATOR.nameNl} (ondernemingsnummer ${n.OPERATOR.enterprise}, btw ${n.OPERATOR.vat}), ${n.OPERATOR.addressNl}`,o={updated:"Van kracht sinds 21 oktober 2026",nav:{mentions:"Wettelijke vermeldingen",conditions:"Algemene voorwaarden",confidentialite:"Privacy",cookies:"Cookies",suppression:"Account verwijderen"},docs:{mentions:{title:"Wettelijke vermeldingen",sections:[{title:"Uitgever",body:[`BatiNode (${n.OPERATOR.site}) wordt uitgegeven en uitgebaat door ${t}.`,`Contact: ${n.OPERATOR.email}.`]},{title:"Hosting",body:["De webapplicatie wordt aangeboden via GitHub Pages (GitHub, Inc., 88 Colin P. Kelly Jr. Street, San Francisco, CA 94107, Verenigde Staten).","De gegevens van accounts, aanvragen, offertes en bestanden worden gehost door Supabase, Inc. in een datacenter in Frankfurt (Duitsland, Europese Unie)."]},{title:"Intellectuele eigendom",body:[`Het merk BatiNode, het logo, Nodi, de teksten, de illustraties en de code van de applicatie behoren toe aan ${n.OPERATOR.nameNl}. Elke overname zonder schriftelijke toestemming is verboden.`,"Namen, logo\u2019s en inhoud van ingeschreven bedrijven blijven eigendom van die bedrijven."]},{title:"Inhoud melden",body:[`Om onwettige inhoud of een fout te melden, schrijf naar ${n.OPERATOR.email}. Wij antwoorden zo snel mogelijk.`]}]},conditions:{title:"Algemene gebruiks- en verkoopvoorwaarden",sections:[{title:"1. Voorwerp",body:[`Deze voorwaarden regelen het gebruik van BatiNode, een platform uitgebaat door ${t}, en de abonnementen die erop verkocht worden.`,"Door een account aan te maken, op een prijsaanvraag te antwoorden of de applicatie te gebruiken, aanvaardt u deze voorwaarden namens het bedrijf dat u vertegenwoordigt."]},{title:"2. Een platform voor professionals",body:["BatiNode richt zich uitsluitend tot bedrijven: bouwaannemers, leveranciers van materialen en architecten. Elk bedrijf moet een actief Belgisch ondernemingsnummer hebben.","Wij controleren het btw-nummer (VIES) en de inschrijving in de Kruispuntbank van Ondernemingen, bij de inschrijving en daarna regelmatig. Een account van een niet-actief bedrijf of met onjuiste gegevens kan worden opgeschort.","U bent verantwoordelijk voor de gegevens die u opgeeft, voor de geheimhouding van uw wachtwoord en voor wat met uw account gebeurt. Meld elk ongeoorloofd gebruik onmiddellijk."]},{title:"3. De diensten",body:["Met BatiNode kunt u onder meer prijsaanvragen naar leveranciers sturen en hun offertes vergelijken, bestelbonnen opmaken, met andere bedrijven communiceren in het Ondernemersnetwerk (onderaanneming en partnerschappen), bestanden beheren en hulp krijgen van Nodi, de assistent van BatiNode.","Welke functies beschikbaar zijn, hangt af van het gekozen abonnement, zoals vermeld op de pagina Abonnement in de applicatie."]},{title:"4. De rol van BatiNode",body:["BatiNode brengt bedrijven met elkaar in contact. Wij zijn geen partij bij de overeenkomsten tussen hen: de verkoop van materialen wordt rechtstreeks gesloten tussen de aannemer en de leverancier, onder de voorwaarden van hun offerte en bestelbon.","Wij waarborgen geen prijzen, kwaliteit, termijnen of solvabiliteit van gebruikers. De controle van bedrijven beperkt de risico\u2019s, maar sluit ze niet uit.","Kiest de aannemer zelf geen leveranciers, dan selecteert BatiNode leveranciers uit de regio op basis van hun activiteit en nabijheid, zonder tegenprestatie van hun kant."]},{title:"5. Abonnementen voor aannemers",body:["Een nieuwe aannemer kan het Premium-abonnement 7 dagen gratis uitproberen, zonder betaalkaart. Na de proefperiode stopt de toegang tot de betalende functies tot er een abonnement gekozen wordt.","Lanceringsprijzen exclusief btw: Starter 69,99 \u20ac per maand of 699,90 \u20ac per jaar; Premium 129,99 \u20ac per maand of 1 299,90 \u20ac per jaar. De Belgische btw komt bovenop de prijs.","Stichtersgarantie: een bedrijf dat zich tijdens de lanceringsfase abonneert, dat wil zeggen bij de eerste 50 bedrijven die een abonnement betalen en uiterlijk op 31 maart 2027 (Belgische tijd), krijgt een stichtersnummer en behoudt zijn lanceringsprijs levenslang, zolang het abonnement zonder onderbreking actief blijft op hetzelfde plan. De stichter kan \xe9\xe9n keer van Starter naar Premium overstappen met behoud van deze garantie, tegen de lanceringsprijs van Premium. De garantie vervalt als het abonnement wordt opgezegd, naar een lagere formule overstapt of een tweede keer van formule verandert.","De betaling verloopt via Stripe. Het abonnement wordt vooraf betaald en wordt aan het einde van elke periode automatisch verlengd, tegen de dan geldende prijs.","Tevreden of terugbetaald: uw eerste abonnementsbetaling wordt volledig terugbetaald als u daarom vraagt via support@batinode.be binnen 30 dagen na de betaling, zonder reden. Het abonnement wordt dan opgezegd en een eventuele stichtersplaats wordt niet opnieuw toegekend. Deze garantie geldt \xe9\xe9n keer per bedrijf.","U kunt op elk moment opzeggen in de applicatie: de opzegging gaat in aan het einde van de betaalde periode, zonder terugbetaling van de lopende periode.","Onder voorbehoud van de stichtersgarantie kondigen wij elke prijsverhoging minstens 30 dagen vooraf aan; ze geldt vanaf de volgende periode en u kunt vooraf opzeggen.","Omdat de abonnementen aan bedrijven verkocht worden, geldt het herroepingsrecht voor consumenten niet."]},{title:"6. Leveranciers",body:["Een leverancier kan op een prijsaanvraag antwoorden via de link in de e-mail, zonder account. Antwoorden is gratis.","Een ingediende offerte verbindt de leverancier tot de vermelde prijzen en voorwaarden, tot de geldigheidsdatum. De leverancier blijft verantwoordelijk voor zijn offerte, ook wanneer hij een pdf heeft toegevoegd en Nodi de prijzen heeft overgenomen: hij controleert het formulier voor hij het verstuurt.","Mocht er een commissie op bestellingen ingevoerd worden, dan wordt het percentage getoond en uitdrukkelijk aanvaard v\xf3\xf3r elke betrokken offerte. Ze geldt nooit voor reeds ingediende offertes.","Een leverancier kan op elk moment stoppen met aanvragen ontvangen, met \xe9\xe9n klik in de e-mail of op de offertepagina."]},{title:"7. Nodi en artifici\xeble intelligentie",body:["Nodi gebruikt een model van artifici\xeble intelligentie om vragen te beantwoorden, als pdf toegevoegde offertes te lezen, het nieuws te schrijven en berichten tussen aannemers en leveranciers te herformuleren of te vertalen. Contactgegevens worden uit doorgestuurde berichten verwijderd.","Antwoorden van Nodi kunnen fouten bevatten. Ze vervangen geen professioneel advies (technisch, juridisch of fiscaal). Controleer altijd bedragen en belangrijke informatie.","Het nieuws dat Nodi publiceert, vat artikels van externe bronnen samen, met vermelding van de link. Die bronnen blijven verantwoordelijk voor hun inhoud."]},{title:"8. Verboden gebruik",body:["Het is onder meer verboden: onwettige, misleidende, beledigende inhoud te publiceren of inhoud die de rechten van anderen schendt; ongevraagde reclameberichten te sturen; gegevens van het platform massaal te kopi\xebren; te proberen toegang te krijgen tot accounts of gegevens van anderen; de werking van de dienst te verstoren; een account aan te maken voor een bedrijf dat u niet vertegenwoordigt."]},{title:"9. Uw inhoud",body:["U blijft eigenaar van de inhoud die u plaatst (aanvragen, offertes, bestanden, berichten, logo). U geeft ons het recht die te hosten, te tonen aan de gekozen ontvangers en te verwerken voor zover nodig voor de werking van de dienst."]},{title:"10. Beschikbaarheid en aansprakelijkheid",body:["Wij doen het nodige om BatiNode beschikbaar en veilig te houden, zonder een dienst zonder onderbreking of fouten te kunnen waarborgen. Er kan onderhoud plaatsvinden.",`Behalve bij opzet of zware fout is de aansprakelijkheid van ${n.OPERATOR.nameNl} beperkt tot rechtstreekse schade en tot de bedragen die uw bedrijf in de 12 maanden v\xf3\xf3r het schadegeval aan BatiNode betaald heeft. Wij zijn niet aansprakelijk voor onrechtstreekse schade, zoals verlies van omzet, klanten of gegevens.`]},{title:"11. Opschorting en einde",body:["U kunt op elk moment stoppen met BatiNode en de verwijdering van uw account vragen.","Wij kunnen een account dat deze voorwaarden niet naleeft opschorten of sluiten, na een waarschuwing behalve bij hoogdringendheid (fraude, veiligheid, onwettige inhoud)."]},{title:"12. Persoonsgegevens",body:["De verwerking van persoonsgegevens wordt beschreven in het privacybeleid, dat deel uitmaakt van deze voorwaarden."]},{title:"13. Wijziging van de voorwaarden",body:["Wij kunnen deze voorwaarden aanpassen. Elke belangrijke wijziging wordt minstens 30 dagen vooraf aangekondigd, per e-mail of in de applicatie. Gaat u niet akkoord, dan kunt u v\xf3\xf3r die datum opzeggen."]},{title:"14. Toepasselijk recht en geschillen",body:["Deze voorwaarden vallen onder het Belgisch recht. Bij onenigheid schrijft u ons eerst: wij zoeken een minnelijke oplossing.","Lukt dat niet, dan zijn uitsluitend de rechtbanken van het gerechtelijk arrondissement Brussel bevoegd."]}]},confidentialite:{title:"Privacybeleid",sections:[{title:"Verwerkingsverantwoordelijke",body:[`${t} is verantwoordelijk voor de verwerking van persoonsgegevens via BatiNode. Voor vragen of verzoeken: ${n.OPERATOR.email}.`]},{title:"Welke gegevens",body:["Account: naam, e-mailadres, telefoon, taal en wachtwoord (enkel versleuteld bewaard).","Bedrijf: naam, btw-nummer, adres, openbare gegevens van de Kruispuntbank van Ondernemingen, logo, vakgebieden, werkgebied, grootte en de gegevens opgegeven bij de inschrijving.","Activiteit: prijsaanvragen, offertes, bestelbonnen, documenten, bestanden, berichten, berichten in het Ondernemersnetwerk en vragen aan Nodi.","Betaling: het abonnement en zijn status. Kaartgegevens worden rechtstreeks door Stripe verwerkt; wij hebben er geen toegang toe.","Technisch: verbindings- en foutlogboeken, IP-adres, voor de veiligheid van de dienst.","Leveranciers: de gids bevat professionele contactgegevens van materiaalleveranciers (bedrijfsnaam, adres, professioneel e-mailadres en telefoon, activiteit), afkomstig uit openbare bronnen zoals hun website of de Kruispuntbank van Ondernemingen."]},{title:"Waarom en op welke grond",body:["De dienst leveren (account, aanvragen, offertes, bestellingen, Ondernemersnetwerk, abonnement): uitvoering van de overeenkomst.","Facturatie en boekhouding: wettelijke verplichting.","Bedrijven controleren, fraude voorkomen, het platform beveiligen: gerechtvaardigd belang bij een betrouwbaar platform.","Prijsaanvragen doorsturen naar leveranciers uit de gids: gerechtvaardigd belang van aannemers en leveranciers om elkaar als professionals te vinden. Elke e-mail laat toe zich met \xe9\xe9n klik te verzetten.","U informeren over de evolutie van de dienst: gerechtvaardigd belang; u kunt zich er altijd tegen verzetten."]},{title:"Wie uw gegevens ziet",body:["Leveranciers die een aanvraag ontvangen, zien de naam, het btw-nummer en het adres van het aanvragende bedrijf en de inhoud van de aanvraag. De aannemer ziet de offertes en de naam van de leveranciers. Persoonlijke contactgegevens worden uit doorgestuurde berichten verwijderd.","Onze verwerkers, enkel om BatiNode te laten werken: Supabase (database en bestanden, Frankfurt, EU), GitHub (hosting van de webapplicatie), Brevo (verzending van e-mails, Frankrijk), Stripe (betalingen) en Anthropic (het AI-model van Nodi). Volgens zijn commerci\xeble voorwaarden gebruikt Anthropic deze gegevens niet om zijn modellen te trainen.","Enkel als u het aanvaardt in de cookiebanner van de webversie: Meta Platforms Ireland (Meta-pixel), om onze Facebook- en Instagram-advertenties te meten. Het ontvangt de bezochte pagina\u2019s en het feit dat een inschrijving of abonnement plaatsvond, nooit uw gegevens, en werkt nooit op de links die naar leveranciers worden gestuurd.","Sommige van deze dienstverleners kunnen gegevens buiten de Europese Unie verwerken, met name in de Verenigde Staten. Die doorgiften gebeuren binnen het EU-VS-kader voor gegevensbescherming of met de standaardcontractbepalingen van de Europese Commissie.","Ingelogde leden van BatiNode zien in de lijst van ingeschreven aannemers de naam van uw bedrijf, uw gemeente, uw vakgebieden en de badges \xab KBO-geverifieerd \xbb en \xab Stichter \xbb. Nooit uw e-mail, telefoon of btw-nummer. U kunt die lijst op elk moment verlaten in Instellingen.","Wij verkopen uw gegevens nooit."]},{title:"Bewaartermijn",body:["Account- en activiteitsgegevens worden bewaard zolang het account actief is, en binnen 30 dagen na een verzoek tot verwijdering gewist of geanonimiseerd, behalve wat de wet ons verplicht te bewaren (facturen en boekhoudstukken, gedurende de wettelijke termijn).","Technische logboeken worden maximaal 12 maanden bewaard.","De gegevens van een leverancier in de gids worden bewaard tot hij zich verzet; dan houden wij enkel bij wat nodig is om zijn weigering te respecteren."]},{title:"Uw rechten",body:[`U kunt inzage, verbetering, wissing, beperking van de verwerking en overdraagbaarheid van uw gegevens vragen, en u verzetten tegen verwerking op basis van ons gerechtvaardigd belang. Schrijf naar ${n.OPERATOR.email}; wij antwoorden binnen een maand.`,"U kunt ook klacht indienen bij de Gegevensbeschermingsautoriteit, Drukpersstraat 35, 1000 Brussel (www.gegevensbeschermingsautoriteit.be)."]},{title:"Beveiliging",body:["Verbindingen zijn versleuteld (HTTPS), wachtwoorden zijn versleuteld, elk bedrijf heeft enkel toegang tot zijn eigen gegevens, bestanden zijn priv\xe9 en openen enkel via tijdelijke links, en beheerderstoegang is beperkt."]}]},cookies:{title:"Cookies en lokale opslag",sections:[{title:"Wat wij gebruiken",body:["In de webversie wordt de Meta-pixel (Facebook, Instagram) pas actief als u op \u201cAanvaarden\u201d klikt in de banner; \u201cWeigeren\u201d is even eenvoudig. Hij dient om onze advertenties te meten: bekeken pagina\u2019s, inschrijving, abonnement, zonder uw gegevens. Hij plaatst de cookie \u201c_fbp\u201d (tot 90 dagen) en stuurt deze gegevens naar Meta Platforms Ireland, dat ze aan uw Facebook- of Instagram-account kan koppelen. Uw keuze wordt 6 maanden bewaard; met de link \u201cCookiekeuze\u201d onderaan de openbare pagina\u2019s kunt u ze wijzigen. De iPhone- en Android-app gebruikt deze pixel niet.","Voor de rest bewaart de applicatie in uw browser of op uw telefoon enkel wat nodig is om te werken: uw aanmeldsessie, de gekozen taal en enkele weergavevoorkeuren (bijvoorbeeld een concept van een aanvraag). Die zijn strikt noodzakelijk en vragen dus geen toestemming."]},{title:"Betaling",body:["De betaalpagina wordt door Stripe op zijn eigen website aangeboden. Stripe gebruikt daar eigen cookies, nodig voor de veiligheid van de betaling en het voorkomen van fraude, volgens zijn eigen beleid."]},{title:"Ze wissen",body:["U kunt deze gegevens op elk moment wissen door u af te melden of via de instellingen van uw browser. U moet zich daarna opnieuw aanmelden."]}]},suppression:{title:"Uw BatiNode-account verwijderen",sections:[{title:"In de app",body:["Open Instellingen, dan \xab Mijn account verwijderen \xbb, en bevestig. De verwijdering is onmiddellijk en definitief."]},{title:"Zonder de app",body:[`Schrijf naar ${n.OPERATOR.email} vanaf het e-mailadres van uw account en vraag de verwijdering. Wij voeren ze binnen 30 dagen uit en bevestigen het u.`]},{title:"Wat verwijderd wordt",body:["Uw toegang en uw persoonsgegevens. Bent u de laatste gebruiker van uw bedrijf: het abonnement wordt stopgezet, de bestanden, het logo, de oproepen en de gesprekken worden gewist.","Wat bewaard blijft: de bestellingen, offertes en boekhoudstukken die uw partners of wijzelf wettelijk moeten bewaren, gedurende de wettelijke termijn, zonder uw contactgegevens."]}]}}}},1049,[1048]);
__d(function(g,r,i,a,m,e,d){"use strict";function n(){return"https://app.batinode.be".replace(/\/$/,'')}Object.defineProperty(e,'__esModule',{value:!0}),e.appUrl=n,e.referralUrl=function(t){return`${n()}/bienvenue?ref=${encodeURIComponent(t)}`},r(d[0])},1050,[104]);